input.sparql:
SELECT ?p ?ts ?label WHERE {
  ?p a brick:ElectricPower ;
     brick:hasSubBuilding ?sub .
  ?p ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}

SELECT DISTINCT ?class WHERE {
  ?p a ?class .
  FILTER(LCASE(?class) CONTAINS "electricepwer" || LCASE(?class) CONTAINS "electricpower")
}

SELECT ?p ?ts WHERE {
  ?p a ?cls .
  FILTER (regex(str(?cls),"lectric","i"))
  ?p ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}
